    for i,a,w in cells:
        a+=join['lane'];ww={'uid':4,'rdui':4,'enum':1}.get(fmt,w); r=b[a:a+ww]; v=int.from_bytes(r,'little'); out=v; reason=None; absent=False
        if fmt=='ref':
