def archive_contents(md):
    p=Path(os.environ.get('FM24_DB_DIR',ROOT/'scratch/data'))
    if p.drive.upper()=='Z:' or p.resolve().drive.upper()=='Z:':raise ValueError('Z: forbidden')
    sys.path.append(str(ROOT.parent/'fm24/tools/python'))
    import zstandard
