            if transfer('a8_present',1):
                ver=b[p];transfer('obj_a8',1+32+4*(ver>=2)+9+(2 if ver>=3 else 1)+8)
            block(['mf0','m1a1','m1a8','mf4','mf5'],[4,1,1,1,1])
            if transfer('e0_present',1):ck(transfer('obj_e0',4)==0,'untraced e0 items')
